"use client";
import type { CSSProperties } from "react";
import { ButtonSurface, buttonVariables, type AnimationButtonProps } from "./button-shared";
export interface RainbowButtonProps extends AnimationButtonProps {
  colors?: readonly string[];
  cycleDuration?: number;
  glow?: number;
  animateAtRest?: boolean;
}
const css = `
.z-anb-rainbow{overflow:visible;border:1px solid transparent;min-height:56.4px;background:linear-gradient(var(--z-anb-background),var(--z-anb-background)) padding-box,linear-gradient(var(--z-anb-background) 50%,transparent) border-box,var(--z-anb-rainbow) border-box;background-size:100% 100%,100% 100%,200% 100%;animation:z-anb-rainbow-flow var(--z-anb-cycle,2s) linear infinite alternate}
.z-anb-rainbow-glow{position:absolute;z-index:-1;pointer-events:none;top:100%;left:50%;width:60%;height:20%;border-radius:50%;background:var(--z-anb-rainbow);background-size:200% 100%;filter:blur(var(--z-anb-glow,12.8px));transform:translateX(-50%);opacity:.7;animation:z-anb-rainbow-flow var(--z-anb-cycle,2s) linear infinite alternate;transition:width var(--z-anb-duration) var(--z-anb-easing),filter var(--z-anb-duration) var(--z-anb-easing),opacity var(--z-anb-duration) var(--z-anb-easing),top var(--z-anb-duration) var(--z-anb-easing)}
.z-anb-rainbow[data-active=true] .z-anb-rainbow-glow{width:90%;top:110%;opacity:1;filter:blur(calc(var(--z-anb-glow,12.8px)*1.5))}.z-anb-rainbow[data-rest=false][data-active=false],.z-anb-rainbow[data-rest=false][data-active=false] .z-anb-rainbow-glow{animation-play-state:paused}
.z-anb-rainbow[disabled],.z-anb-rainbow[disabled] .z-anb-rainbow-glow,.z-anb-rainbow[aria-disabled=true],.z-anb-rainbow[aria-disabled=true] .z-anb-rainbow-glow{animation-play-state:paused}
@keyframes z-anb-rainbow-flow{from{background-position:0% 0%}to{background-position:200% 0%}}
`;
/** A dark face with a traveling rainbow edge and a glow that broadens on hover. */
export function RainbowButton({
  children = "Get Started",
  colors = ["#ff4242", "#a1ff42", "#42a1ff", "#42d0ff", "#a142ff"],
  cycleDuration = 2,
  duration = 0.4,
  glow = 12.8,
  animateAtRest = true,
  background = "#0a0a0a",
  color = "#ffffff",
  easing = "cubic-bezier(.16,1,.3,1)",
  ...props
}: RainbowButtonProps) {
  const gradient = `linear-gradient(90deg,${(colors.length >= 2 ? colors : [colors[0] || "#ff4242", "#a142ff"]).join(",")})`;
  return (
    <>
      <style>{css}</style>
      <ButtonSurface
        {...props}
        variant="rainbow"
        data-rest={animateAtRest}
        variables={
          {
            ...buttonVariables({ ...props, duration, easing, background, color }),
            "--z-anb-rainbow": gradient,
            "--z-anb-cycle": `${Math.max(0.1, cycleDuration)}s`,
            "--z-anb-glow": `${Math.max(0, glow)}px`,
          } as CSSProperties
        }
      >
        <span className="z-anb-rainbow-glow" aria-hidden="true" />
        <span className="z-anb-label">{children}</span>
      </ButtonSurface>
    </>
  );
}
